1	import { betterAuth } from "better-auth";
2	import { bearer } from "better-auth/plugins";
3	
4	export interface AuthEnv {
5	  DB: D1Database;
6	  BETTER_AUTH_SECRET: string;
7	  MIGRATION_SECRET?: string;
8	  BETTER_AUTH_URL: string;
9	  PUBLIC_GAME_URL: string;
10	  BETTER_AUTH_TRUSTED_ORIGINS?: string;
11	}
12	
13	export function trustedOrigins(env: AuthEnv): string[] {
14	  const configured = (env.BETTER_AUTH_TRUSTED_ORIGINS ?? "")
15	    .split(",")
16	    .map((value) => value.trim())
17	    .filter(Boolean);
18	  return [...new Set([...configured, "http://127.0.0.1:3210", env.BETTER_AUTH_URL])];
19	}
20	
21	export function createAuth(env: AuthEnv) {
22	  return betterAuth({
23	    database: env.DB,
24	    baseURL: env.BETTER_AUTH_URL,
25	    secret: env.BETTER_AUTH_SECRET,
26	    trustedOrigins: trustedOrigins(env),
27	    emailAndPassword: {
28	      enabled: true,
29	      // SMTP is optional; friend can turn verification on later.
30	      requireEmailVerification: false,
31	    },
32	    account: {
33	      storeStateStrategy: "cookie",
34	    },
35	    plugins: [bearer()],
36	  });
