2012	// Tokens deliberately skip this: they round-trip through the listener verbatim.
2013	fn percent_decode(value: &str) -> String {
2014	    // Byte-wise on purpose: slicing `value` by byte offsets would panic on a
2015	    // `%` that lands mid-character in malformed input.
2016	    fn hex(byte: u8) -> Option<u8> {
2017	        match byte {
2018	            b'0'..=b'9' => Some(byte - b'0'),
2019	            b'a'..=b'f' => Some(byte - b'a' + 10),
2020	            b'A'..=b'F' => Some(byte - b'A' + 10),
2021	            _ => None,
2022	        }
2023	    }
2024	    let bytes = value.as_bytes();
2025	    let mut out: Vec<u8> = Vec::with_capacity(bytes.len());
2026	    let mut index = 0;
2027	    while index < bytes.len() {
2028	        match (bytes[index], bytes.get(index + 1), bytes.get(index + 2)) {
2029	            (b'%', Some(&high), Some(&low)) => match (hex(high), hex(low)) {
2030	                (Some(high), Some(low)) => {
2031	                    out.push(high * 16 + low);
2032	                    index += 3;
2033	                }
2034	                _ => {
2035	                    out.push(b'%');
2036	                    index += 1;
2037	                }
2038	            },
2039	            (byte, _, _) => {
2040	                out.push(byte);
2041	                index += 1;
2042	            }
2043	        }
2044	    }
2045	    String::from_utf8_lossy(&out).into_owned()
