1	#!/usr/bin/env bun
2	import { join, dirname } from "node:path";
3	import { fileURLToPath } from "node:url";
4	import { createAuthAnalyticsEvent } from "./analytics/events.js";
5	import { analytics } from "./analytics/posthog.js";
6	import { runAuthCommand, type AuthSuccess } from "./auth.js";
7	import { findGame, isPlayable, REGISTRY } from "./games/registry.js";
8	import { launchOverlay as showOverlay } from "../scripts/overlay.js";
9	import { detectInstallContext, writeInstallContext } from "../scripts/plugin-update.js";
10	
11	const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
12	
13	function captureAuthSuccess(result: AuthSuccess): void {
14	  if (result.userId) analytics.setDistinctId(result.userId);
15	  analytics.capture(createAuthAnalyticsEvent(result));
16	}
17	
18	function printUsage(): void {
19	  const ids = REGISTRY.filter(isPlayable).map((entry) => entry.id).join(", ");
20	  console.log("usage: gamepigeon [game]");
21	  console.log("       gamepigeon auth [signup|login|status|logout]");
22	  console.log("       gamepigeon install [--codex|--claude|--opencode|--hermes|--openclaw|--antigravity|--all]");
23	  console.log("       gamepigeon export [--input <file-or-directory>]... [--output <directory>] [--include-noops]");
24	  console.log("");
25	  console.log("With no argument, opens the arcade overlay menu.");
26	  console.log(`Available games: ${ids}`);
27	}
28	
29	async function installAdapters(target?: string): Promise<void> {
30	  const proc = Bun.spawn(["bash", join(ROOT, "scripts/install-adapters.sh"), target ?? "--all"], {
31	    cwd: ROOT,
32	    env: { ...process.env, GAMEPIGEON_WORKSPACE_DIR: process.cwd() },
33	    stdin: "ignore",
34	    stdout: "inherit",
35	    stderr: "inherit",
36	  });
37	  await proc.exited;
38	  if (proc.exitCode !== 0) process.exit(proc.exitCode ?? 1);
39	  // The adapters now point at *this* checkout. Record it immediately so an
