/**
 * Tolerant of both `&` and `?` separators: some hosted redirects append `?token`
 * onto a callback that already carried `?state`, yielding `state=..?token=..`.
 * Values come back exactly as they arrived — a session token has to round-trip
 * verbatim, so decoding happens only where the value is human-facing text.
 */
function queryParam(query: string, key: string): string | undefined {
  for (const pair of query.split(/[&?]/)) {
    const split = pair.indexOf("=");
    if (split < 0) continue;
    if (pair.slice(0, split) === key) return pair.slice(split + 1);
  }
  return undefined;
}

/** Percent-decoding for human-readable query text (OAuth error descriptions). */
function decodeQueryText(value: string): string {
  const spaced = value.replace(/\+/g, " ");
  try {
    return decodeURIComponent(spaced);
  } catch {
    return spaced;
  }
}

/**
 * Turns a failed handoff (`?error=...`) into a sentence worth showing. Capped
 * because it lands in both the browser page and the terminal.
 */
function callbackFailure(query: string): string | undefined {
  const error = queryParam(query, "error");
  if (!error) return undefined;
  if (error === "access_denied") return "Sign-in was cancelled before it finished.";
  const description = decodeQueryText(queryParam(query, "error_description") ?? "");
  const message = description || `The login page reported an error: ${decodeQueryText(error)}`;
  return [...message].slice(0, 200).join("");
}

export interface OAuthCallbackServer {
  /** The port actually bound — not always the requested one, see the fallback below. */
  readonly port: number;
  /** Resolves once the socket is bound and `port` has its final value. */
  ready: Promise<void>;
  /** Resolves with the raw token from the callback query, or rejects on error/cancel. */
  token: Promise<string>;
  close(): void;
}

// Pages carry a session token in their URL — keep them out of caches and out of
// the Referer sent to anything they link to.
function reply(response: ServerResponse, status: number, contentType: string, body: string): void {
  response.writeHead(status, {
    "content-type": contentType,
    "content-length": Buffer.byteLength(body),
    "cache-control": "no-store",
    "referrer-policy": "no-referrer",
    connection: "close",
  });
  response.end(body);
}

/**
 * The localhost listener the browser hands the finished sign-in back to.
 * Returns synchronously so the caller can build a callback URL immediately;
 * `ready` is what tells you the socket is up.
 *
 * The token is handed over raw and unverified, and any `state` is accepted:
 * unlike the overlay's Rust listener (`tauri/src/main.rs`), which generates and
 * checks its own nonce, this one is given nothing to compare against.
 * Verification against the auth backend is the caller's job.
 */
export function startOAuthCallbackServer(port: number): OAuthCallbackServer {
  let resolveToken!: (token: string) => void;
  let rejectToken!: (error: Error) => void;
  const token = new Promise<string>((resolve, reject) => {
    resolveToken = resolve;
    rejectToken = reject;
  });
  // A caller may only care about serving the page; never let that look like an
  // unhandled rejection.
  void token.catch(() => {});
  let settled = false;
  const succeed = (value: string): void => {
    if (settled) return;
    settled = true;
    resolveToken(value);
  };
  const fail = (message: string): void => {
    if (settled) return;
    settled = true;
    rejectToken(new Error(message));
  };

  const server = createServer((request, response) => {
    const target = request.url ?? "/";
    const split = target.indexOf("?");
    const path = split < 0 ? target : target.slice(0, split);
    const query = split < 0 ? "" : target.slice(split + 1);

    // The Worker's readiness probe: it checks the CLI is still listening before
    // sending the browser onward.
    if (path === "/auth/ping") {
      reply(response, 200, "text/plain; charset=utf-8", "ok");
      return;
    }
    if (path !== "/auth/callback") {
      reply(response, 404, "text/plain; charset=utf-8", "not found");
      return;
    }
    // A login page that gave up hands back `error` instead of `token`; saying
    // why beats the generic "did not return a session token".
    const failure = callbackFailure(query);
    if (failure) {
      reply(response, 400, "text/html; charset=utf-8", signInFailedPage(escapeHtml(failure)));
      fail(failure);
      return;
    }
    const value = queryParam(query, "token");
    if (!value) {
      const reason = "The login page came back without a session token.";
      reply(response, 400, "text/html; charset=utf-8", signInFailedPage(escapeHtml(reason)));
      fail(reason);
      return;
    }
    reply(response, 200, "text/html; charset=utf-8", signedInPage());
    succeed(value);
  });

  let boundPort = port;
  let resolveReady!: () => void;
  let rejectReady!: (error: Error) => void;
  const ready = new Promise<void>((resolve, reject) => {
    resolveReady = resolve;
    rejectReady = reject;
  });
  void ready.catch(() => {});

  const bind = (candidate: number, allowFallback: boolean): void => {
    const onError = (error: NodeJS.ErrnoException): void => {
      // Another sign-in (a second terminal, or the overlay) already owns the
      // fixed port; any free port works, since the Worker is told where to
      // send the browser.
      if (allowFallback && error.code === "EADDRINUSE") {
        bind(0, false);
        return;
      }
      const message = `Could not start the sign-in listener: ${error.message}`;
      rejectReady(new Error(message));
      fail(message);
    };
    server.once("error", onError);
    server.listen(candidate, "127.0.0.1", () => {
      server.off("error", onError);
      const address = server.address();
      if (address && typeof address === "object") boundPort = address.port;
      resolveReady();
    });
  };
  bind(port, true);

  return {
    get port(): number {
      return boundPort;
    },
    ready,
    token,
    close(): void {
      server.closeAllConnections?.();
      server.close();
    },
  };
}

/**
 * Arc (and Dia, same vendor) route links from other apps into a "Little Arc"
 * window, which drops the login page's redirect chain — the tab either never
 * appears or dies mid-handoff, so sign-in silently never completes. Asking Arc
 * for a real tab in a real window over AppleScript bypasses Little Arc
 * entirely, the same way the desktop overlay does it.
 */
export function isArcBundle(bundleId: string): boolean {
  const id = bundleId.toLowerCase();
  return id === "company.thebrowser.browser" || id === "company.thebrowser.dia";
}

function applescriptEscape(value: string): string {
  return value.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
}

/** The AppleScript that opens `url` as a real tab in a real Arc/Dia window. */
export function arcTabScript(bundleId: string, url: string): string {
  return `tell application id "${applescriptEscape(bundleId)}"
    activate
    if (count of windows) is 0 then
        make new window
    end if
    tell front window to make new tab with properties {URL:"${applescriptEscape(url)}"}
end tell`;
}

/**
 * Runs an opener and reports whether it actually succeeded. Spawning alone
 * can't tell us that — `xdg-open` with no handler and `open` with a broken
 * default browser both fail *after* the spawn — so we wait for the exit status.
 */
function runOpener(command: string, args: string[]): boolean {
  try {
    const result = spawnSync(command, args, { stdio: "ignore" });
    return !result.error && result.status === 0;
  } catch {
    return false;
  }
}

/**
 * `defaults read` prints one dict per registered handler; the role and the
 * scheme are separate lines inside the same `{ ... }` block, so we scan block by
 * block for the one claiming `https`.
 */
export function parseDefaultHttpsHandler(plist: string): string | undefined {
  const prefix = "LSHandlerRoleAll = ";
  for (const block of plist.split("{")) {
    if (!block.includes("LSHandlerURLScheme = https;")) continue;
    const line = block.split("\n").find((entry) => entry.trimStart().startsWith(prefix));
    if (!line) continue;
    const value = line.trim().slice(prefix.length).replace(/;$/, "").replace(/^"|"$/g, "");
    if (value) return value;
  }
  return undefined;
}

/**
 * The bundle id macOS would hand an `https` URL to, read from LaunchServices.
 * Used only to detect Arc; any parse failure just means we take the ordinary
 * `open` path.
 */
function defaultHttpsHandler(): string | undefined {
  const result = spawnSync(
    "defaults",
    ["read", "com.apple.LaunchServices/com.apple.launchservices.secure"],
    { encoding: "utf8" },
  );
  if (result.error || result.status !== 0 || !result.stdout) return undefined;
  return parseDefaultHttpsHandler(result.stdout);
}

/**
 * Hands the sign-in URL to the user's browser. Returns false when every opener
 * we know about failed — the caller then leads with the printed link instead of
 * claiming a browser is opening.
 */
function openBrowser(url: string): boolean {
  if (process.platform === "darwin") {
    const bundleId = defaultHttpsHandler();
    if (bundleId && isArcBundle(bundleId) && runOpener("osascript", ["-e", arcTabScript(bundleId, url)])) {
      return true;
    }
    // Safari is the last resort: it is always present, so a broken or missing
    // default handler still gets the user to the login page.
    return runOpener("open", [url]) || runOpener("open", ["-a", "Safari", url]);
  }
  if (process.platform === "win32") {
    return runOpener("cmd", ["/c", "start", "", url])
      || runOpener("rundll32", ["url.dll,FileProtocolHandler", url]);
  }
  return runOpener("xdg-open", [url])
    || runOpener("gio", ["open", url])
    || runOpener("x-www-browser", [url]);
}

async function withTimeout<T>(work: Promise<T>, ms: number, message: string): Promise<T> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  try {
    return await Promise.race([
      work,
      new Promise<never>((_resolve, reject) => {
        timer = setTimeout(() => reject(new Error(message)), ms);
      }),
    ]);
  } finally {
    if (timer) clearTimeout(timer);
  }
}

function isOAuthProvider(value: string): value is OAuthProvider {
  return (oauthProviders as readonly string[]).includes(value);
}

/**
 * Browser sign-in: the Worker starts the provider handshake and hands the
 * finished session back to the listener started here. The Worker — not the CLI
 * — decides whether a provider is usable, so an unconfigured provider surfaces
 * as its error page rather than a local guess.
 */
async function runOAuthCommand(providerArg?: string): Promise<AuthSuccess> {
  const provider = (providerArg ?? "").toLowerCase();
  if (!isOAuthProvider(provider)) {
    throw new Error("usage: gamepigeon auth oauth [google|github]");
  }
  const authBaseUrl = requireAuthBaseUrl();
  const callback = startOAuthCallbackServer(defaultCallbackPort);
  try {
    await callback.ready;
    const next = `http://127.0.0.1:${callback.port}/auth/callback`;
    const url = `${authBaseUrl}/cli/oauth?provider=${provider}&next=${encodeURIComponent(next)}`;
    const opened = openBrowser(url);
    console.log(
      opened
        ? `Opening ${provider} sign-in in your browser. Finish there, then come back.`
        : "Could not open a browser automatically.",
    );
    console.log(`If nothing opens, visit:\n  ${url}`);

    const token = await withTimeout(callback.token, signInTimeoutMs, "Sign-in timed out. Try again.");
    const user = await resolveUser(token);
    saveSession(token, user);
    console.log(`Signed in as ${user.email}`);
    return { kind: "signed_in", method: provider, userId: user.id };
  } finally {
    callback.close();
  }
}

export type { AuthUser, StoredSession };

