@media (max-width:400px){.card{padding:28px 20px 24px}h1{font-size:21px}}`;

const CHECK_ICON = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 6 9 17l-5-5"/></svg>`;
const ALERT_ICON = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 7.5v5.5"/><path d="M12 16.5h.01"/></svg>`;

export function escapeHtml(value: string): string {
  let out = "";
  for (const character of value) {
    if (character === "&") out += "&amp;";
    else if (character === "<") out += "&lt;";
    else if (character === ">") out += "&gt;";
    else if (character === '"') out += "&quot;";
    else if (character === "'") out += "&#39;";
    else out += character;
  }
  return out;
}

interface ArcadePage {
  tone: "ok" | "warn";
  title: string;
  lead: string;
  steps?: string[];
  hint?: string;
  /** Extra `<head>` markup, e.g. a `<meta http-equiv="refresh">` fallback. */
  head?: string;
  /** Extra markup after the card, e.g. the inline redirect script. */
  tail?: string;
}

