    tone: "warn",
    title: "Sign in first",
    lead: "This page hands a signed-in session back to Tui, and there's no session in this browser yet.",
    steps: [
      "Run <code>gamepigeon auth oauth google</code> or <code>gamepigeon auth oauth github</code> in your terminal.",
