import { betterAuth } from "better-auth";
import { bearer } from "better-auth/plugins";

export interface AuthEnv {
  DB: D1Database;
  BETTER_AUTH_SECRET: string;
  MIGRATION_SECRET?: string;
  BETTER_AUTH_URL: string;
  PUBLIC_GAME_URL: string;
  BETTER_AUTH_TRUSTED_ORIGINS?: string;
  GOOGLE_CLIENT_ID?: string;
  GOOGLE_CLIENT_SECRET?: string;
  GITHUB_CLIENT_ID?: string;
  GITHUB_CLIENT_SECRET?: string;
}

/** The providers the CLI and the overlay may ask for by name. */
export const oauthProviders = ["google", "github"] as const;

export type OAuthProvider = (typeof oauthProviders)[number];

export function isOAuthProvider(value: string | null): value is OAuthProvider {
  return value !== null && (oauthProviders as readonly string[]).includes(value);
}

/**
 * A provider is usable only when both halves of its credential pair are set.
 * Deployments enable Google and GitHub independently (and local `.dev.vars`
 * often has neither), so this is checked per request rather than at startup.
 */
export function oauthCredentials(
  env: AuthEnv,
  provider: OAuthProvider,
): { clientId: string; clientSecret: string } | null {
  const clientId = provider === "google" ? env.GOOGLE_CLIENT_ID : env.GITHUB_CLIENT_ID;
  const clientSecret = provider === "google" ? env.GOOGLE_CLIENT_SECRET : env.GITHUB_CLIENT_SECRET;
  if (!clientId || !clientSecret) return null;
  return { clientId, clientSecret };
}

function socialProviders(env: AuthEnv): Record<string, { clientId: string; clientSecret: string }> {
  const configured: Record<string, { clientId: string; clientSecret: string }> = {};
  for (const provider of oauthProviders) {
    const credentials = oauthCredentials(env, provider);
    if (credentials) configured[provider] = credentials;
  }
  return configured;
}

export function trustedOrigins(env: AuthEnv): string[] {
  const configured = (env.BETTER_AUTH_TRUSTED_ORIGINS ?? "")
    .split(",")
    .map((value) => value.trim())
    .filter(Boolean);
  return [...new Set([...configured, "http://127.0.0.1:3210", env.BETTER_AUTH_URL])];
}

export function createAuth(env: AuthEnv) {
  return betterAuth({
    database: env.DB,
    baseURL: env.BETTER_AUTH_URL,
    secret: env.BETTER_AUTH_SECRET,
    trustedOrigins: trustedOrigins(env),
    emailAndPassword: {
      enabled: true,
      // SMTP is optional; friend can turn verification on later.
      requireEmailVerification: false,
    },
    account: {
      storeStateStrategy: "cookie",
    },
    socialProviders: socialProviders(env),
    plugins: [bearer()],
  });
}

