/**
 * The two browser-facing routes a CLI sign-in walks through:
 *
 *   `gamepigeon auth oauth google`
 *     -> GET /cli/oauth?provider=google&next=http://127.0.0.1:3210/auth/callback
 *     -> the provider's consent screen
 *     -> GET /api/auth/callback/google   (Better Auth sets the session cookie)
 *     -> GET /cli/handoff?next=http://127.0.0.1:3210/auth/callback
 *     -> http://127.0.0.1:3210/auth/callback?token=<session token>
 *
 * `next` is attacker-reachable — it arrives in a URL the user can be sent — and
 * the last hop hands it a live session token, so both routes refuse anything but
 * a plain-http loopback address before they touch a session.
 */
import {
  createAuth,
  isOAuthProvider,
  oauthCredentials,
  oauthProviders,
  type AuthEnv,
} from "./auth";
import {
  escapeHtml,
  handoffRedirectPage,
  handoffRefusedPage,
  signInRequiredPage,
} from "./handoff-page";

/** Better Auth's default session cookie name. */
const sessionCookieName = "better-auth.session_token";

function page(status: number, body: string): Response {
  return new Response(body, {
    status,
    headers: {
      "content-type": "text/html; charset=utf-8",
      // The success page's redirect target carries a session token: never let a
      // cache or a downstream page keep hold of it.
      "cache-control": "no-store",
      "referrer-policy": "no-referrer",
    },
  });
}

function refused(status: number, reason: string): Response {
  return page(status, handoffRefusedPage(escapeHtml(reason)));
}

/**
 * The only `next` targets we will ever attach a token to: a plain-http loopback
 * URL, which is the one place a token cannot leave this machine. Everything else
 * — https, a hostname that merely looks local, a `javascript:` or `data:` URL, a
 * scheme-relative `//evil.example` — is rejected.
 */
export function parseCliNext(raw: string | null): URL | null {
  if (!raw) return null;
  let next: URL;
  try {
    next = new URL(raw);
  } catch {
    return null;
  }
  if (next.protocol !== "http:") return null;
  if (next.hostname !== "127.0.0.1" && next.hostname !== "localhost") return null;
  return next;
}

/**
 * The literal session cookie value, read straight from the `Cookie` header:
 * that string is what the CLI replays as its bearer token, and it is not
 * something the object `getSession` returns is guaranteed to expose.
 */
export function sessionCookieToken(cookieHeader: string | null): string | null {
  if (!cookieHeader) return null;
  for (const entry of cookieHeader.split(";")) {
    const split = entry.indexOf("=");
    if (split < 0) continue;
    const name = entry.slice(0, split).trim();
    // Over HTTPS the same cookie is served under Better Auth's `__Secure-`
    // prefix; both spellings carry the identical signed value.
    if (name !== sessionCookieName && name !== `__Secure-${sessionCookieName}`) continue;
    const value = entry.slice(split + 1).trim();
    if (value) return value;
  }
  return null;
}

/**
 * Appends `token` to whatever query `next` already carries — the CLI puts its
 * own `state` there — rather than replacing the query. The value goes on
 * verbatim: it is the cookie's already-encoded form, and re-encoding it would
 * hand the CLI a token that no longer verifies.
 */
export function callbackUrlWithToken(next: URL, token: string): string {
  const separator = next.search ? "&" : "?";
  return `${next.origin}${next.pathname}${next.search}${separator}token=${token}${next.hash}`;
}

/**
 * Hands the browser's signed-in session back to the CLI listener at `next`.
 * Serves a redirecting page rather than a 302 so the visible copy explains what
 * just happened when the local listener is already gone.
 */
export async function handleCliHandoff(request: Request, env: AuthEnv): Promise<Response> {
  const next = parseCliNext(new URL(request.url).searchParams.get("next"));
  if (!next) {
    return refused(
      400,
      "This sign-in link points somewhere Tui will not send a session. Start the sign-in from your terminal.",
    );
  }

  const token = sessionCookieToken(request.headers.get("cookie"));
  let signedIn = false;
  try {
    const session = await createAuth(env).api.getSession({ headers: request.headers });
    signedIn = Boolean(session?.user);
  } catch {
    // A cookie we cannot resolve is not a session. Failing closed here keeps a
    // stale or forged cookie on the same path as no cookie at all.
    signedIn = false;
  }
  if (!signedIn || !token) return page(401, signInRequiredPage());

  return page(200, handoffRedirectPage(callbackUrlWithToken(next, token)));
}

/**
 * Starts the provider handshake for a CLI sign-in and sends the browser on to
 * the provider, carrying the state cookie Better Auth just issued.
 */
export async function handleCliOAuth(request: Request, env: AuthEnv): Promise<Response> {
  const query = new URL(request.url).searchParams;
  const provider = query.get("provider");
  if (!isOAuthProvider(provider)) {
    return refused(400, `Tui signs in with ${oauthProviders.join(" or ")}, not "${provider ?? ""}".`);
  }
  if (!oauthCredentials(env, provider)) {
    return refused(503, `${provider} sign-in is not configured on this server yet.`);
  }
  const next = parseCliNext(query.get("next"));
  if (!next) {
    return refused(
      400,
      "This sign-in link points somewhere Tui will not send a session. Start the sign-in from your terminal.",
    );
  }

  const handoff = `${env.BETTER_AUTH_URL.replace(/\/$/, "")}/cli/handoff?next=${encodeURIComponent(next.toString())}`;
  // The API is called without a Request on purpose: this is a top-level browser
  // navigation we have already validated, not a cross-site form post.
  const started = await createAuth(env).api.signInSocial({
    body: {
      provider,
      callbackURL: handoff,
      // A provider that fails or is cancelled goes straight back to the CLI, so
      // the terminal reports the reason instead of hanging.
      errorCallbackURL: next.toString(),
    },
    asResponse: true,
  });
  const payload = await started.clone().json<{ url?: string }>().catch(() => null);
  if (!started.ok || !payload?.url) {
    return refused(502, `Could not start ${provider} sign-in. Try again in a moment.`);
  }

  // Copied from the Better Auth response so its `set-cookie` (the OAuth state)
  // rides along with the redirect.
  const headers = new Headers(started.headers);
  headers.set("location", payload.url);
  headers.set("cache-control", "no-store");
  headers.set("referrer-policy", "no-referrer");
  headers.delete("content-type");
  headers.delete("content-length");
  return new Response(null, { status: 302, headers });
}

