describe("the OAuth callback listener", () => {
  async function listening(port = 0): Promise<OAuthCallbackServer> {
    const server = startOAuthCallbackServer(port);
    await server.ready;
    return server;
  }

  function callbackUrl(server: OAuthCallbackServer, query: string): string {
    return `http://127.0.0.1:${server.port}/auth/callback${query}`;
  }

  test("answers the readiness probe and hands back the raw token", async () => {
    const server = await listening();
    try {
      const ping = await fetch(`http://127.0.0.1:${server.port}/auth/ping`);
      expect(ping.status).toBe(200);
      expect(await ping.text()).toBe("ok");

      // A redirect that glued `?token` onto the existing `?state` still parses.
      const landing = await fetch(callbackUrl(server, "?state=nonce?token=tok.sig"));
      expect(landing.status).toBe(200);
      expect(landing.headers.get("cache-control")).toBe("no-store");
      expect(await landing.text()).toContain("signed in");
      expect(await server.token).toBe("tok.sig");
    } finally {
      server.close();
    }
  });

  test("ignores whatever state it is handed, having no nonce of its own", async () => {
    const server = await listening();
    try {
      await fetch(callbackUrl(server, "?state=some-other-attempt&token=tok.sig"));
      expect(await server.token).toBe("tok.sig");
    } finally {
      server.close();
    }
  });

  test("404s anything that is not the callback", async () => {
    const server = await listening();
    try {
      const response = await fetch(`http://127.0.0.1:${server.port}/`);
      expect(response.status).toBe(404);
    } finally {
      server.close();
    }
  });

  test("reports a cancelled sign-in", async () => {
    const server = await listening();
    try {
      const response = await fetch(callbackUrl(server, "?error=access_denied"));
      expect(response.status).toBe(400);
      expect((await response.text()).toLowerCase()).toContain("cancelled");
      await expect(server.token).rejects.toThrow(/cancelled/i);
    } finally {
      server.close();
    }
  });

  test("escapes the provider's reason in the page but not in the error", async () => {
    const server = await listening();
    const description = "<script>alert(1)</script> broke";
    try {
      const response = await fetch(
        callbackUrl(server, `?error=server_error&error_description=${encodeURIComponent(description)}`),
      );
      expect(response.status).toBe(400);
      const body = await response.text();
      expect(body).toContain("&lt;script&gt;alert(1)&lt;/script&gt; broke");
      expect(body).not.toContain("<script>");
      await expect(server.token).rejects.toThrow(description);
    } finally {
      server.close();
    }
  });

  test("rejects a callback that arrives without a token", async () => {
    const server = await listening();
    try {
      const response = await fetch(callbackUrl(server, "?state=nonce"));
      expect(response.status).toBe(400);
      expect(await response.text()).toContain("without a session token");
      await expect(server.token).rejects.toThrow(/session token/);
    } finally {
      server.close();
    }
  });

  test("falls back to a free port when the requested one is taken", async () => {
    const first = await listening();
    const second = await listening(first.port);
    try {
      expect(second.port).not.toBe(first.port);
      const ping = await fetch(`http://127.0.0.1:${second.port}/auth/ping`);
      expect(await ping.text()).toBe("ok");
    } finally {
      second.close();
      first.close();
    }
  });
});

describe("browser routing on macOS", () => {
  test("sends Arc and Dia down the AppleScript path", () => {
    expect(isArcBundle("company.thebrowser.Browser")).toBe(true);
    expect(isArcBundle("company.thebrowser.dia")).toBe(true);
    expect(isArcBundle("com.google.Chrome")).toBe(false);
    expect(isArcBundle("com.apple.Safari")).toBe(false);
  });

  test("asks Arc for a real tab in a real window", () => {
    const script = arcTabScript("company.thebrowser.Browser", "https://auth.example/cli/oauth?provider=google");
    expect(script).toContain('tell application id "company.thebrowser.Browser"');
    expect(script).toContain("if (count of windows) is 0 then");
    expect(script).toContain(
      'tell front window to make new tab with properties {URL:"https://auth.example/cli/oauth?provider=google"}',
    );
  });

  test("escapes quotes and backslashes so the script cannot be broken out of", () => {
    const script = arcTabScript('com.evil"\\', 'https://auth.example/?x="\\');
    expect(script).toContain('tell application id "com.evil\\"\\\\"');
    expect(script).toContain('{URL:"https://auth.example/?x=\\"\\\\"}');
  });

  test("reads the default https handler out of the LaunchServices plist", () => {
    const plist = `{
    LSHandlerPreferredVersions =     {
        LSHandlerRoleAll = "-";
    };
    LSHandlerRoleAll = "com.apple.mail";
    LSHandlerURLScheme = mailto;
},
{
    LSHandlerRoleAll = "company.thebrowser.Browser";
    LSHandlerURLScheme = https;
}`;
    expect(parseDefaultHttpsHandler(plist)).toBe("company.thebrowser.Browser");
    expect(parseDefaultHttpsHandler("{ LSHandlerURLScheme = ftp; }")).toBeUndefined();
  });
});

test("browser sign-in rejects a provider Tui does not offer", async () => {
  await expect(runAuthCommand("oauth", "slack")).rejects.toThrow(/google\|github/);
  await expect(runAuthCommand("oauth")).rejects.toThrow(/google\|github/);
});
