import { getMigrations } from "better-auth/db/migration";
import { env, exports } from "cloudflare:workers";
import { beforeAll, describe, expect, test } from "vitest";
import { createAuth, type AuthEnv } from "../src/auth";
import {
  callbackUrlWithToken,
  handleCliHandoff,
  handleCliOAuth,
  parseCliNext,
  sessionCookieToken,
} from "../src/cli-handoff";

const callback = "http://127.0.0.1:3210/auth/callback";
const withCredentials: AuthEnv = {
  ...env,
  GOOGLE_CLIENT_ID: "google-test-client",
  GOOGLE_CLIENT_SECRET: "google-test-secret",
};

function get(path: string, headers: Record<string, string> = {}): Request {
  return new Request(`${env.BETTER_AUTH_URL}${path}`, { headers });
}

function oauth(next: string, provider = "google"): Request {
  return get(`/cli/oauth?provider=${provider}&next=${encodeURIComponent(next)}`);
}

describe("next targets", () => {
  test.each([
    callback,
    "http://localhost:3210/auth/callback",
    "http://127.0.0.1:51234/auth/callback?state=nonce",
  ])("trusts the loopback target %s", (raw) => {
    expect(parseCliNext(raw)?.href).toBe(new URL(raw).href);
  });

  test.each([
    "https://127.0.0.1:3210/auth/callback",
    "http://127.0.0.1.evil.example/auth/callback",
    "http://localhost.evil.example/auth/callback",
    "http://evil.example/auth/callback",
    "javascript:fetch('/cli/handoff')",
    "data:text/html,<script>1</script>",
    "//127.0.0.1:3210/auth/callback",
    "/auth/callback",
    "",
  ])("refuses %s", (raw) => {
    expect(parseCliNext(raw)).toBeNull();
  });

  test("refuses a missing target", () => {
    expect(parseCliNext(null)).toBeNull();
  });
});

describe("token attachment", () => {
  test("keeps the query the CLI already put on the callback", () => {
    expect(callbackUrlWithToken(new URL(`${callback}?state=nonce`), "tok.sig"))
      .toBe(`${callback}?state=nonce&token=tok.sig`);
  });

  test("starts a query when there is none", () => {
    expect(callbackUrlWithToken(new URL(callback), "tok.sig")).toBe(`${callback}?token=tok.sig`);
  });

  test("reads the literal session cookie value, ignoring its neighbours", () => {
    expect(sessionCookieToken("other=1; better-auth.session_token=tok.sig; another=2"))
      .toBe("tok.sig");
    expect(sessionCookieToken("__Secure-better-auth.session_token=tok.sig")).toBe("tok.sig");
    expect(sessionCookieToken("better-auth.session_data=cached")).toBeNull();
    expect(sessionCookieToken(null)).toBeNull();
  });
});

describe("GET /cli/oauth", () => {
  test("rejects a provider it does not support", async () => {
    for (const provider of ["slack", "GOOGLE_", "", "email"]) {
      const response = await handleCliOAuth(oauth(callback, provider), withCredentials);
      expect(response.status).toBe(400);
    }
  });

  test("reports an unconfigured provider as unavailable", async () => {
    const response = await handleCliOAuth(oauth(callback, "github"), withCredentials);
    expect(response.status).toBe(503);
    expect(await response.text()).toContain("github");
  });

  test("refuses an untrusted next before starting sign-in", async () => {
    const response = await handleCliOAuth(oauth("https://evil.example/steal"), withCredentials);
    expect(response.status).toBe(400);
  });

  test("redirects to the provider and carries the state cookie", async () => {
    const response = await handleCliOAuth(oauth(`${callback}?state=nonce`), withCredentials);
    expect(response.status).toBe(302);
    const location = new URL(response.headers.get("location") ?? "");
    expect(location.hostname).toBe("accounts.google.com");
    expect(location.searchParams.get("client_id")).toBe("google-test-client");
    expect(location.searchParams.get("redirect_uri"))
      .toBe(`${env.BETTER_AUTH_URL}/api/auth/callback/google`);
    expect(response.headers.get("set-cookie")).toContain("better-auth");
    expect(response.headers.get("cache-control")).toBe("no-store");
  });
});

describe("GET /cli/handoff", () => {
  test("refuses an untrusted next before looking at the session", async () => {
    for (const next of ["https://evil.example/steal", "http://evil.example/steal", ""]) {
      const response = await handleCliHandoff(
        get(`/cli/handoff?next=${encodeURIComponent(next)}`),
        env,
      );
      expect(response.status).toBe(400);
    }
  });

  test("asks an anonymous browser to start from the CLI", async () => {
    const response = await handleCliHandoff(
      get(`/cli/handoff?next=${encodeURIComponent(callback)}`),
      env,
    );
    expect(response.status).toBe(401);
    expect((await response.text()).toLowerCase()).toContain("oauth");
  });

  test("treats a cookie that resolves to no session as anonymous", async () => {
    const response = await handleCliHandoff(
      get(`/cli/handoff?next=${encodeURIComponent(callback)}`, {
        cookie: "better-auth.session_token=not-a-real-token.signature",
      }),
      env,
    );
    expect(response.status).toBe(401);
  });
});

describe("a signed-in browser handing back to the CLI", () => {
  let cookie = "";

  beforeAll(async () => {
    const { runMigrations } = await getMigrations(createAuth(env).options);
    await runMigrations();
    const signedUp = await exports.default.fetch(
      new Request(`${env.BETTER_AUTH_URL}/api/auth/sign-up/email`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({
          email: "handoff@example.com",
          password: "test-only-password",
          name: "Handoff",
        }),
      }),
    );
    expect(signedUp.status).toBe(200);
    cookie = (signedUp.headers.get("set-cookie") ?? "").split(";")[0] ?? "";
    expect(cookie).toContain("session_token=");
  });

  test("redirects to the callback with the session token appended", async () => {
    const response = await handleCliHandoff(
      get(`/cli/handoff?next=${encodeURIComponent(`${callback}?state=nonce`)}`, { cookie }),
      env,
    );
    expect(response.status).toBe(200);
    expect(response.headers.get("cache-control")).toBe("no-store");

    const token = cookie.slice(cookie.indexOf("=") + 1);
    const body = await response.text();
    // Un-escaped, so the `&` between `state` and `token` survives into the CLI.
    expect(body).toContain(`${callback}?state=nonce&token=${token}`);
    expect(body).toContain("location.replace(");
  });

  test("hands the token back through the worker's own route", async () => {
    const response = await exports.default.fetch(
      new Request(`${env.BETTER_AUTH_URL}/cli/handoff?next=${encodeURIComponent(callback)}`, {
        headers: { cookie },
      }),
    );
    expect(response.status).toBe(200);
    expect(await response.text()).toContain(`${callback}?token=`);
  });
});

