async function resolveUser(sessionToken: string): Promise<AuthUser> {
  const { response, json } = await authRequest("/get-session", { method: "GET" }, sessionToken);
  if (!response.ok || !json?.user?.id || !json.user.email) {
    throw new Error(errorMessage(json, "Could not load the signed-in user."));
  }
  return { id: json.user.id, email: json.user.email };
}

/**
 * Tolerant of both `&` and `?` separators: some hosted redirects append `?token`
 * onto a callback that already carried `?state`, yielding `state=..?token=..`.
 * Values come back exactly as they arrived — a session token has to round-trip
 * verbatim, so decoding happens only where the value is human-facing text.
 */
function queryParam(query: string, key: string): string | undefined {
  for (const pair of query.split(/[&?]/)) {
    const split = pair.indexOf("=");
    if (split < 0) continue;
    if (pair.slice(0, split) === key) return pair.slice(split + 1);
  }
  return undefined;
}

/** Percent-decoding for human-readable query text (OAuth error descriptions). */
function decodeQueryText(value: string): string {
  const spaced = value.replace(/\+/g, " ");
  try {
    return decodeURIComponent(spaced);
  } catch {
    return spaced;
  }
}

/**
 * Turns a failed handoff (`?error=...`) into a sentence worth showing. Capped
 * because it lands in both the browser page and the terminal.
 */
function callbackFailure(query: string): string | undefined {
  const error = queryParam(query, "error");
  if (!error) return undefined;
  if (error === "access_denied") return "Sign-in was cancelled before it finished.";
  const description = decodeQueryText(queryParam(query, "error_description") ?? "");
  const message = description || `The login page reported an error: ${decodeQueryText(error)}`;
  return [...message].slice(0, 200).join("");
}

